Here’s a clear, practical path to convert GPX to JSON in Python, with two approaches (with and without external libraries), plus sample inputs and outputs.

What we’re converting
- GPX is XML containing waypoints (wpt), routes (rte), and tracks (trk with segments and points).
- JSON target is a clean Python dict you can serialize.

Approach 1: Using gpxpy (simple and robust)
Install
- pip install gpxpy

Code: gpx_to_json.py
import json
import gpxpy
import gpxpy.gpx
from typing import Any, Dict, List, Optional

def point_to_dict(p) -> Dict[str, Any]:
    d = {
        "lat": p.latitude,
        "lon": p.longitude,
    }
    if p.elevation is not None:
        d["ele"] = p.elevation
    if p.time is not None:
        d["time"] = p.time.isoformat()
    if p.speed is not None:
        d["speed"] = p.speed
    if p.extensions:
        d["extensions"] = p.extensions
    return d

def waypoint_to_dict(w) -> Dict[str, Any]:
    d = point_to_dict(w)
    if w.name:
        d["name"] = w.name
    if w.description:
        d["desc"] = w.description
    if w.symbol:
        d["sym"] = w.symbol
    if w.type:
        d["type"] = w.type
    return d

def route_to_dict(r) -> Dict[str, Any]:
    return {
        "name": r.name,
        "desc": r.description,
        "points": [point_to_dict(p) for p in r.points],
    }

def track_to_dict(t) -> Dict[str, Any]:
    return {
        "name": t.name,
        "segments": [
            {
                "points": [point_to_dict(p) for p in s.points]
            }
            for s in t.segments
        ],
    }

def gpx_file_to_json_dict(path: str) -> Dict[str, Any]:
    with open(path, "r", encoding="utf-8") as f:
        gpx = gpxpy.parse(f)

    meta = {}
    if gpx.name:
        meta["name"] = gpx.name
    if gpx.description:
        meta["desc"] = gpx.description
    if gpx.author_name:
        meta["author"] = gpx.author_name
    if gpx.time:
        meta["time"] = gpx.time.isoformat()

    return {
        "metadata": meta or None,
        "waypoints": [waypoint_to_dict(w) for w in gpx.waypoints],
        "routes": [route_to_dict(r) for r in gpx.routes],
        "tracks": [track_to_dict(t) for t in gpx.tracks],
    }

if __name__ == "__main__":
    import sys, pathlib
    if len(sys.argv) != 3:
        print("Usage: python gpx_to_json.py input.gpx output.json")
        sys.exit(1)
    data = gpx_file_to_json_dict(sys.argv[1])
    pathlib.Path(sys.argv[2]).write_text(json.dumps(data, indent=2), encoding="utf-8")
    print(f"Wrote {sys.argv[2]}")

