import json
import xml.etree.ElementTree as ET

GPX_NS = {"g": "http://www.topografix.com/GPX/1/1"}

def get_text(elem, tag):
    t = elem.find(f"g:{tag}", GPX_NS)
    return t.text if t is not None else None

def parse_point(elem):
    lat = float(elem.attrib["lat"])
    lon = float(elem.attrib["lon"])
    d = {"lat": lat, "lon": lon}
    ele = get_text(elem, "ele")
    if ele is not None:
        d["ele"] = float(ele)
    time = get_text(elem, "time")
    if time is not None:
        d["time"] = time
    return d

def parse_waypoints(root):
    out = []
    for w in root.findall("g:wpt", GPX_NS):
        d = parse_point(w)
        name = get_text(w, "name")
        if name:
            d["name"] = name
        desc = get_text(w, "desc")
        if desc:
            d["desc"] = desc
        sym = get_text(w, "sym")
        if sym:
            d["sym"] = sym
        typ = get_text(w, "type")
        if typ:
            d["type"] = typ
        out.append(d)
    return out

def parse_routes(root):
    routes = []
    for r in root.findall("g:rte", GPX_NS):
        pts = []
        for rp in r.findall("g:rtept", GPX_NS):
            pts.append(parse_point(rp))
        routes.append({
            "name": get_text(r, "name"),
            "desc": get_text(r, "desc"),
            "points": pts
        })
    return routes

def parse_tracks(root):
    tracks = []
    for t in root.findall("g:trk", GPX_NS):
        segs = []
        for s in t.findall("g:trkseg", GPX_NS):
            pts = [parse_point(p) for p in s.findall("g:trkpt", GPX_NS)]
            segs.append({"points": pts})
        tracks.append({
            "name": get_text(t, "name"),
            "segments": segs
        })
    return tracks

def gpx_to_json_dict(path):
    tree = ET.parse(path)
    root = tree.getroot()
    meta = {}
    name = get_text(root, "name")
    desc = get_text(root, "desc")
    time = get_text(root, "time")
    if name: meta["name"] = name
    if desc: meta["desc"] = desc
    if time: meta["time"] = time
    return {
        "metadata": meta or None,
        "waypoints": parse_waypoints(root),
        "routes": parse_routes(root),
        "tracks": parse_tracks(root)
    }

if __name__ == "__main__":
    import sys, pathlib
    if len(sys.argv) != 3:
        print("Usage: python gpx_to_json_stdlib.py input.gpx output.json")
        raise SystemExit(1)
    data = gpx_to_json_dict(sys.argv[1])
    pathlib.Path(sys.argv[2]).write_text(json.dumps(data, indent=2), encoding="utf-8")
    print(f"Wrote {sys.argv[2]}")

Running the stdlib script on tiny.gpx produces the same JSON shape as above.

Command-line one-liner (stdin to stdout)
python - << 'PY'
import sys, json, gpxpy
g = gpxpy.parse(sys.stdin.read())
out = {
  "waypoints":[{"lat":w.latitude,"lon":w.longitude,"name":w.name} for w in g.waypoints],
  "tracks":[{"name":t.name,"segments":[{"points":[{"lat":p.latitude,"lon":p.longitude} for p in s.points]} for s in t.segments]} for t in g.tracks]
}
print(json.dumps(out, indent=2))
PY < input.gpx

Notes and pitfalls
- Namespaces: when not using gpxpy, always use the GPX 1.1 namespace in XPath (as shown).
- Large files: prefer iterparse to stream points without loading all in memory (xml.etree.ElementTree.iterparse).
- Timezones: GPX times are usually UTC (Z). If you need epoch seconds, parse with datetime.fromisoformat or dateutil and convert.
- Numeric precision: keep lat/lon as floats; if you need fixed precision, round during serialization.
- Extensions: vendor extensions vary; with gpxpy you can access point.extensions and copy through as-is if needed.

